/**
 * dsh-proxy host plugin: mounts the authenticated LAN reverse proxy on a
 * second port, forwarding the web app's loopback listener (127.0.0.1:3080 by
 * default) to the LAN with a web-based login gate. The harness deliberately
 * refuses `--host 0.0.0.0` for the web server itself — remote code execution
 * exposure — so this plugin is the sanctioned way to serve the surface beyond
 * loopback, with authentication in front.
 *
 * The plugin also mounts the settings API as an exact `POST /api/dsh-proxy`
 * route on Connection's shared `/api` channel: `status` reads the running
 * proxy, `update` persists a settings patch (target upstream port, username,
 * password) into the profile's private state directory and restarts the
 * forwarding service — the backend of the settings section. Connection owns
 * the carrier, so the route inherits its Host/Origin trust fence and browser
 * session check.
 */
import type { Context } from '@deepseek-ai/cordis'
// Kept after the type import: the file's leading JSDoc is emitted into
// lib/types/index.d.ts only when it stays attached to a retained declaration.
import { join } from 'node:path'
import z from '@deepseek-ai/schemastery'
// Type-only: merges `ctx.webServer` into the Context type.
import type {} from '@deepseek-ai/dsh-host-webserver'
// Type-only: merges `ctx.connection` (host Connection Fetch-route registry).
import type {} from '@deepseek-ai/dsh-client-connection'
import { dshHomePath } from '@deepseek-ai/dsh-home-paths'
import { ProxyController } from './controller.ts'
import { SESSION_COOKIE, readCookie } from './auth.ts'
import { normalizeOAuthConfig } from './oauth/config.ts'
import { requestOriginOf } from './oauth/origin.ts'
import { defaultOAuthConfig, type OAuthConfig } from './oauth/providers.ts'
import {
  PROXY_STATE_FILES,
  type StateScope,
  resolveStateDir,
  seedLegacyState,
} from './state-dir.ts'
import {
  ENDPOINT_AUDIT,
  ENDPOINT_AUTH,
  ENDPOINT_AUTH_REVOKE,
  ENDPOINT_OAUTH_BINDING_REMOVE,
  ENDPOINT_OAUTH_BINDING_START,
  ENDPOINT_OAUTH_STATUS,
  ENDPOINT_OAUTH_UPDATE,
  ENDPOINT_SECURITY,
  ENDPOINT_START,
  ENDPOINT_STATUS,
  ENDPOINT_STOP,
  ENDPOINT_UPDATE,
  LAN_PROXY_PATH,
  type LanProxyFailure,
  type LanProxyRequest,
  type LanProxyResult,
} from './contract.ts'

// Standalone API for scripts and smoke tests, exercised through the same
// bundled artifact the profile loads.
export { lanAddresses, startLanProxy } from './proxy.ts'
export type { LanProxyHandle, LanProxyOptions } from './proxy.ts'
export { AuthState } from './auth.ts'
export { AuditTrail } from './audit.ts'

/** Stable Cordis plugin name (the Loader entry and package name). */
export const name = '@stack-brain/dsh-proxy'

/** Services required before load: the web server (upstream port source) and the Connection carrier. */
export const inject = ['webServer', 'connection']

/** Plugin configuration, validated at load by the Loader. */
export interface Config {
  /** Interface the proxy binds; 0.0.0.0 exposes the LAN. */
  listenHost: string
  /** Port the proxy listens on (must differ from the web app's port). */
  listenPort: number
  /** Upstream DSH bind host. */
  upstreamHost: string
  /** Upstream DSH port; 0 follows the web app's actual bound port. */
  upstreamPort: number
  /** Login / Basic Auth username; password login is enabled only when both it and `password` are set. */
  username: string
  /** Login / Basic Auth password; password login is enabled only when both it and `username` are set. */
  password: string
  /**
   * Addresses whose `X-Forwarded-*` headers are believed — the TLS-terminating
   * reverse proxy in front of this listener. Loopback is always trusted.
   */
  trustedProxies: string[]
  /**
   * Refuse plain HTTP entirely instead of serving the native Basic Auth dialog
   * there. Off by default: LAN-over-HTTP is a supported deployment.
   */
  requireTls: boolean
  /**
   * Where the three persisted state files live. `profile` (default) gives each
   * profile its own `$DSH_HOME/profiles/<name>/dsh-proxy/` directory, so one
   * profile's settings page never changes another's; `home` keeps the legacy
   * shared file set directly in `$DSH_HOME`.
   */
  stateScope: StateScope
  /** Third-party login config; official endpoints apply unless overridden. */
  oauth?: OAuthConfig
}

/**
 * The OAuth subtree is normalized by `normalizeOAuthConfig` (tolerant of any
 * deployment YAML, fills every default), so the schemastery node only needs to
 * carry a complete default value. `z.any` also keeps declaration emit from
 * referencing cosmokit's internal `Dict` through deeply nested object schemas.
 */
const emptyOAuthConfig = (): OAuthConfig => defaultOAuthConfig()

/** Configuration schema; deployment-varying bounds stay tunable from cordis.yml. */
export const Config = z.object({
  listenHost: z.string().default('0.0.0.0'),
  listenPort: z.natural().max(65535).default(3081),
  upstreamHost: z.string().default('127.0.0.1'),
  upstreamPort: z.natural().max(65535).default(0),
  username: z.string().default(''),
  password: z.string().default(''),
  trustedProxies: z.array(z.string()).default([]),
  requireTls: z.boolean().default(false),
  stateScope: z.union([z.const('profile'), z.const('home')]).default('profile'),
  oauth: z.any<OAuthConfig>().default(emptyOAuthConfig()),
})

/** One endpoint failure in the shared result envelope. */
function failure(message: string): LanProxyResult<never> {
  const error: LanProxyFailure = { code: 'bad-request', message, details: { issues: [] } }
  return { ok: false, error }
}

/**
 * Build the handler mounted at {@link LAN_PROXY_PATH} on Connection's shared
 * `/api` channel. Connection has already applied its Host/Origin fence and the
 * browser session check by the time a request arrives here, so the handler only
 * decodes the plugin's JSON envelope and dispatches one endpoint.
 *
 * A malformed body answers `400`; endpoint-level failures — including an
 * unknown endpoint — answer `200` with the same `{ ok: false }` envelope so the
 * settings section renders them like any other result.
 *
 * @param controller - the proxy controller this route drives.
 * @returns Fetch handler for the plugin's exact route.
 */
export function createLanProxyRoute(
  controller: ProxyController,
  /**
   * Resolves the caller's own session token from a request (the proxy's login
   * cookie), so "revoke all others" cannot log the caller out of the very page
   * they are clicking from. Optional: without it, `all` still revokes every
   * session the caller could otherwise not have addressed individually.
   */
  currentSessionToken?: (request: Request) => string | undefined,
): (request: Request) => Promise<Response> {
  const dispatch = async (
    endpoint: string,
    payload: unknown,
    currentToken: string | undefined,
    /** Origin the settings page used for this RPC; drives dynamic callback hints. */
    requestOrigin?: string,
  ): Promise<LanProxyResult<unknown>> => {
    if (endpoint === ENDPOINT_STATUS) {
      return { ok: true, value: await controller.refreshStatus() }
    }
    if (endpoint === ENDPOINT_START) {
      const outcome = await controller.start()
      if (!outcome.ok) {
        // The listener did not bind (e.g. the port is taken): answer with the
        // real reason so the settings page reports it instead of claiming the
        // proxy started.
        return failure(outcome.message)
      }
      return { ok: true, value: await controller.refreshStatus() }
    }
    if (endpoint === ENDPOINT_STOP) {
      // Answered before the listener closes so the response survives when the
      // caller is connected through the proxy.
      return { ok: true, value: controller.stopDeferred() }
    }
    if (endpoint === ENDPOINT_UPDATE) {
      const outcome = await controller.update(payload)
      if (outcome.ok) return { ok: true, value: outcome.result }
      return failure(outcome.message)
    }
    if (endpoint === ENDPOINT_AUTH) {
      return { ok: true, value: controller.authView(currentToken) }
    }
    if (endpoint === ENDPOINT_AUDIT) {
      return { ok: true, value: controller.auditView() }
    }
    if (endpoint === ENDPOINT_AUTH_REVOKE) {
      return { ok: true, value: controller.revokeSessions(payload, currentToken) }
    }
    if (endpoint === ENDPOINT_SECURITY) {
      const outcome = controller.updateSecurity(payload)
      if (outcome.ok) return { ok: true, value: outcome }
      return failure(outcome.message)
    }
    if (endpoint === ENDPOINT_OAUTH_STATUS) {
      const view = controller.oauthStatus(requestOrigin)
      return view === null ? failure('第三方登录未初始化') : { ok: true, value: view }
    }
    if (endpoint === ENDPOINT_OAUTH_UPDATE) {
      const outcome = controller.updateOAuth(payload, requestOrigin)
      return outcome.ok ? { ok: true, value: outcome.view } : failure(outcome.message)
    }
    if (endpoint === ENDPOINT_OAUTH_BINDING_START) {
      const outcome = controller.startOAuthBinding(payload, requestOrigin)
      return outcome.ok ? { ok: true, value: { startUrl: outcome.startUrl } } : failure(outcome.message)
    }
    if (endpoint === ENDPOINT_OAUTH_BINDING_REMOVE) {
      const outcome = controller.removeOAuthBinding(payload, requestOrigin)
      return outcome.ok ? { ok: true, value: outcome.view } : failure(outcome.message)
    }
    return failure(`unknown endpoint ${JSON.stringify(endpoint)}`)
  }

  return async (request) => {
    let body: LanProxyRequest
    try {
      body = (await request.json()) as LanProxyRequest
    } catch {
      return Response.json(failure('body is not JSON'), { status: 400 })
    }
    if (typeof body?.endpoint !== 'string' || body.endpoint.length === 0) {
      return Response.json(failure('body has no endpoint'), { status: 400 })
    }
    // Derive the caller's origin server-side from the browser's own Origin /
    // Referer headers, so displayed callback URIs follow the current page
    // without a hardcoded host or a spoofable client-supplied hint.
    const requestOrigin = requestOriginOf({
      url: request.url,
      originHeader: request.headers.get('origin'),
      referer: request.headers.get('referer'),
      host: request.headers.get('host'),
    })
    const result = await dispatch(
      body.endpoint,
      body.payload,
      currentSessionToken === undefined ? undefined : currentSessionToken(request),
      requestOrigin,
    )
    return Response.json(result)
  }
}

/**
 * Mount the proxy and the settings route as effects on this plugin's fiber:
 * unloading the plugin closes the listener, every upgraded socket, and the
 * route.
 * @param ctx - host cordis context.
 * @param config - validated plugin configuration (schema defaults applied).
 */
export function apply(ctx: Context, config?: Config): void {
  const resolved = Config(config ?? {})
  const log = (level: 'info' | 'warn' | 'error', message: string): void => {
    ctx.logger[level](message)
  }

  // Each profile gets its own state files. The loader anchors baseUrl at the
  // profile root's cordis.yml; a child context falls back to the root one.
  // Anything unexpected degrades to the legacy shared home instead of
  // breaking the load, and old home-root files are copied over once.
  const dshHome = dshHomePath()
  const baseUrl: string | undefined = ctx.baseUrl ?? ctx.root?.baseUrl
  const state = resolveStateDir({ baseUrl, dshHome, scope: resolved.stateScope })
  if (state.fallbackReason !== undefined) {
    log('warn', `dsh-proxy: 无法按 profile 隔离状态文件（${state.fallbackReason}），已回退到 $DSH_HOME 共享目录`)
  }
  const migrated = seedLegacyState(state.dir, dshHome)
  if (migrated.length > 0) {
    log('info', `dsh-proxy: 旧配置已从 $DSH_HOME 迁移到 ${state.dir}（${migrated.join(', ')}）；旧文件保留`)
  }
  log('info', `dsh-proxy: 状态目录 ${state.dir}${state.profile === undefined ? '（共享）' : `（profile: ${state.profile}）`}`)

  const controller = new ProxyController({
    base: {
      listenHost: resolved.listenHost,
      listenPort: resolved.listenPort,
      upstreamHost: resolved.upstreamHost,
      upstreamPort: resolved.upstreamPort || ctx.webServer.port || 3080,
      username: resolved.username,
      password: resolved.password,
    },
    settingsFile: join(state.dir, PROXY_STATE_FILES.settings),
    auditFile: join(state.dir, PROXY_STATE_FILES.audit),
    securityFile: join(state.dir, PROXY_STATE_FILES.security),
    oauthBase: normalizeOAuthConfig(resolved.oauth, defaultOAuthConfig()),
    oauthFile: join(state.dir, PROXY_STATE_FILES.oauth),
    trustedProxyAddresses: resolved.trustedProxies,
    requireTls: resolved.requireTls,
    loginTitle: 'DSH 局域网代理',
    // DSH mints its browser-session cookie only through the tokenized URL it
    // prints at startup, which points at loopback. Rebuild that URL for the
    // authority the browser actually used so a LAN visitor's first index
    // request logs itself in instead of dead-ending on "dsh web
    // authentication required".
    authenticatedUrl: (publicOrigin) => {
      try {
        return ctx.connection.authenticatedUrl(publicOrigin)
      } catch {
        return undefined
      }
    },
    log,
  })

  ctx.effect(
    async () => {
      await controller.start()
      return () => controller.stop()
    },
    'dsh-proxy.proxy',
  )

  ctx.effect(
    () =>
      ctx.connection.fetch.register({
        path: LAN_PROXY_PATH,
        methods: ['POST'],
        requestBody: 'buffered',
        // The caller's own session cookie (when the page came through the proxy's
        // login gate) identifies which session must survive a "revoke others".
        fetch: createLanProxyRoute(controller, (request) =>
          readCookie(request.headers.get('cookie') ?? undefined, SESSION_COOKIE)),
      }),
    'dsh-proxy.settings-route',
  )
}
